// generated by build.mjs from calc.mjs
window.MROC=(function(){
// Marrowby Record Office — rules and arithmetic. The build and the browser use the same functions
// (build.mjs strips `export` and writes assets/calc.js).

const NOW = { iso: '2026-10-13', min: 9 * 60 + 40, label: 'Tue 13 Oct 2026, 09:40 BST' };
const OPEN = { from: 9 * 60 + 30, to: 16 * 60 + 30 };
const DESKS = 12;
const SLOTS = [
  { key: 'am', label: 'Morning', time: '09:30 – 12:30' },
  { key: 'pm', label: 'Afternoon', time: '13:30 – 16:30' },
];
const BOOK_DAYS = 60;
// Closed every Sunday and Monday, and on these dates
const CLOSED_DATES = { '2026-12-24': 'Christmas Eve', '2026-12-25': 'Christmas Day', '2026-12-26': 'Boxing Day', '2026-12-31': 'New Year’s Eve', '2027-01-01': 'New Year’s Day' };
const ROUNDS = [600, 690, 840, 930];
const CUTOFF = 45;
const PER_ROUND = 3;
const ZONES = [
  { key: 'a', name: 'Strongroom A', walk: 10 },
  { key: 'b', name: 'Strongroom B', walk: 15 },
  { key: 'map', name: 'Map Store', walk: 20 },
  { key: 'base', name: 'Basement', walk: 25 },
  { key: 'off', name: 'Off-site', walk: 0 },
];
const PRICES = {
  paper: { a4: 0.6, a3: 1.2, a1: null },
  scan: { a4: 1.3, a3: 1.55, a1: 9.5 },
  permit: 5,
  post: 3,
  days: { room: 5, post: 10 },
};
const DEPOSIT = { years: 30, box: 0.1, perMetre: 42, maxMetres: 20 };

const DAY = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

const hhmm = (m) => String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0');
const parseTime = (s) => {
  const m = /^(\d{1,2}):(\d{2})$/.exec(String(s).trim());
  if (!m || +m[1] > 23 || +m[2] > 59) return null;
  return +m[1] * 60 + +m[2];
};
const utc = (iso) => { const [y, m, d] = iso.split('-').map(Number); return Date.UTC(y, m - 1, d); };
const addDays = (iso, n) => new Date(utc(iso) + n * 864e5).toISOString().slice(0, 10);
const daysBetween = (a, b) => Math.round((utc(b) - utc(a)) / 864e5);
const dow = (iso) => new Date(utc(iso)).getUTCDay();
const dateLabel = (iso) => { const d = new Date(utc(iso)); return `${DAY[d.getUTCDay()]} ${d.getUTCDate()} ${MON[d.getUTCMonth()]}`; };
const validIso = (s) => /^\d{4}-\d{2}-\d{2}$/.test(s) && !isNaN(utc(s)) && new Date(utc(s)).toISOString().slice(0, 10) === s;

const closedReason = (iso) => {
  if (CLOSED_DATES[iso]) return CLOSED_DATES[iso];
  const d = dow(iso);
  if (d === 0) return 'Closed on Sundays';
  if (d === 1) return 'Closed on Mondays';
  return null;
};
const nextOpen = (iso) => { let d = addDays(iso, 1); while (closedReason(d)) d = addDays(d, 1); return d; };

// Desks already booked: a fixed number per date and session, worked out from the date string
const hash = (s) => { let h = 2166136261; for (const c of s) { h ^= c.charCodeAt(0); h = Math.imul(h, 16777619); } return h >>> 0; };
const desksFree = (iso, slot) => {
  if (closedReason(iso)) return null;
  const v = hash(iso + '/' + slot + '/mro27') % 15;
  return v > 12 ? 0 : v;
};

// Request at minute `t` on `day` from `zone` → which pull round, and when it reaches the reading room
const pull = (zoneKey, t, day = NOW.iso) => {
  const z = ZONES.find((x) => x.key === zoneKey);
  if (z.key === 'off') {
    const d = nextOpen(day);
    return { zone: z.name, day: d, round: 600, arrive: 600, offsite: true };
  }
  let d = day;
  let i = closedReason(d) ? -1 : ROUNDS.findIndex((r) => t <= r - CUTOFF);
  let moved = false;
  if (i < 0) { d = nextOpen(d); i = 0; moved = true; }
  return { zone: z.name, day: d, round: ROUNDS[i], arrive: ROUNDS[i] + z.walk, cutoff: ROUNDS[i] - CUTOFF, moved, missed: i > 0 && !moved ? ROUNDS[i - 1] : null };
};

// Slip: up to 3 items a round per reader; the rest move to the next round
const assignRounds = (zones, t = NOW.min, day = NOW.iso) => {
  const used = {};
  return zones.map((zk) => {
    let p = pull(zk, t, day);
    if (p.offsite) return p; // the van brings every off-site item at 10:00
    let key = p.day + p.round;
    while ((used[key] || 0) >= PER_ROUND) {
      const i = ROUNDS.indexOf(p.round);
      const z = ZONES.find((x) => x.key === zk);
      const nd = i === ROUNDS.length - 1 ? nextOpen(p.day) : p.day;
      const nr = i === ROUNDS.length - 1 ? ROUNDS[0] : ROUNDS[i + 1];
      p = { ...p, day: nd, round: nr, arrive: nr + z.walk, bumped: true };
      key = p.day + p.round;
    }
    used[key] = (used[key] || 0) + 1;
    return p;
  });
};

const money = (n) => '£' + n.toFixed(2);

const copyQuote = ({ size, method, sheets, delivery }) => {
  if (method === 'permit') return { ok: true, total: PRICES.permit, days: 0, lines: [['Self-photography permit, one day', PRICES.permit]] };
  if (!Number.isInteger(sheets) || sheets < 1 || sheets > 500) return { ok: false, field: 'sheets', error: 'Enter a whole number of sheets from 1 to 500.' };
  const each = PRICES[method][size];
  if (each == null) return { ok: false, field: 'size', error: 'Maps at A1 are scanned only. Choose Scan or a self-photography permit.' };
  const lines = [[`${sheets} × ${size.toUpperCase()} ${method === 'paper' ? 'paper copy' : 'scan'} at ${money(each)}`, Math.round(each * sheets * 100) / 100]];
  if (delivery === 'post') lines.push(['Postage', PRICES.post]);
  const total = lines.reduce((a, [, v]) => a + v, 0);
  return { ok: true, total, days: PRICES.days[delivery], lines };
};

const depositCheck = ({ latest, amount, unit, personal, year = 2026 }) => {
  if (!Number.isInteger(latest) || latest < 1000 || latest > year) return { ok: false, field: 'latest', error: `Enter a year from 1000 to ${year}.` };
  if (!(amount > 0) || amount > 999) return { ok: false, field: 'amount', error: 'Enter an amount above 0.' };
  const metres = Math.ceil(Math.round((unit === 'boxes' ? amount * DEPOSIT.box : amount) * 1000) / 100) / 10;
  const age = year - latest;
  const openYear = latest + DEPOSIT.years;
  return {
    ok: true, metres, age, openYear,
    accept: age >= DEPOSIT.years,
    review: personal,
    large: metres > DEPOSIT.maxMetres,
    fee: Math.round(metres * DEPOSIT.perMetre * 100) / 100,
  };
};

return {NOW,OPEN,DESKS,SLOTS,BOOK_DAYS,CLOSED_DATES,ROUNDS,CUTOFF,PER_ROUND,ZONES,PRICES,DEPOSIT,DAY,MON,hhmm,parseTime,utc,addDays,daysBetween,dow,dateLabel,validIso,closedReason,nextOpen,hash,desksFree,pull,assignRounds,money,copyQuote,depositCheck};
})();
